def build_client_session(api_key: Optional[str]=None, proxies: Optional[
    Dict[str, str]]=None, headers: Optional[Dict[str, str]]=None) ->Tuple[
    SafetyAuthSession, Dict[str, Any]]:
    host_config = get_host_config()
    proxy_config = get_proxy_config()

    if proxies is None:
        proxies = get_proxy_dict(
            proxy_protocol=proxy_config.get('protocol', None),
            proxy_host=proxy_config.get('host', None),
            proxy_port=proxy_config.get('port', None)
        ) if proxy_config else {}

    keys = get_keys(OPENID_CONFIG_URL)

    redirect_url = get_redirect_url()

    client = SafetyAuthSession(
        client_id=CLIENT_ID,
        api_key=api_key,
    )

    if proxies:
        client.proxies = proxies

    if headers:
        client.headers.update(headers)

    client.mount('https://s3.amazonaws.com', S3PresignedAdapter())

    auth_info = get_auth_info()

    organization = None
    if auth_info:
        org_data = get_organization()
        if org_data:
            organization = Organization(**org_data) if isinstance(org_data, dict) else org_data

    return client, keys

def inject_session(func: Callable) ->Callable:
    @wraps(func)
    def wrapper(*args, **kwargs):
        ctx = click.get_current_context()

        api_key = kwargs.get('key', None)
        proxy_host = kwargs.get('proxy_host', None)
        proxy_port = kwargs.get('proxy_port', 80)
        proxy_protocol = kwargs.get('proxy_protocol', 'https')

        proxies = get_proxy_dict(
            proxy_protocol=proxy_protocol,
            proxy_host=proxy_host,
            proxy_port=proxy_port
        ) if proxy_host else None

        if ctx and ctx.obj and hasattr(ctx.obj, 'auth') and ctx.obj.auth.client:
            session = ctx.obj.auth.client
            if api_key:
                session.api_key = api_key
            if proxies:
                session.proxies = proxies
        else:
            session, keys = build_client_session(api_key=api_key, proxies=proxies)
            if ctx and ctx.obj and hasattr(ctx.obj, 'auth'):
                ctx.obj.auth.client = session
                ctx.obj.auth.keys = keys

        kwargs['session'] = session

        return func(*args, **kwargs)

    return wrapper
